create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,plan text not null default 'basic' check(plan in ('basic','premium')),created_at timestamptz not null default now());
create table if not exists public.dogs(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,name text not null,breed text,created_at timestamptz not null default now());
create table if not exists public.health_records(id uuid primary key default gen_random_uuid(),dog_id uuid not null references public.dogs(id) on delete cascade,title text not null,record_date date not null,notes text,created_at timestamptz not null default now());
create table if not exists public.medications(id uuid primary key default gen_random_uuid(),dog_id uuid not null references public.dogs(id) on delete cascade,name text not null,schedule text,notes text,created_at timestamptz not null default now());
create table if not exists public.vaccinations(id uuid primary key default gen_random_uuid(),dog_id uuid not null references public.dogs(id) on delete cascade,vaccine_name text not null,vaccination_date date,due_date date,status text not null default 'Upcoming',created_at timestamptz not null default now());
create table if not exists public.routines(id uuid primary key default gen_random_uuid(),dog_id uuid not null references public.dogs(id) on delete cascade,title text not null,time_of_day time,frequency text not null default 'daily',active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.appointments(id uuid primary key default gen_random_uuid(),dog_id uuid not null references public.dogs(id) on delete cascade,appointment_at timestamptz not null,clinic_name text,reason text,notes text,created_at timestamptz not null default now());
create or replace function public.owns_dog(dog_uuid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.dogs where id=dog_uuid and owner_id=auth.uid()); $$;
alter table public.profiles enable row level security;alter table public.dogs enable row level security;alter table public.health_records enable row level security;alter table public.medications enable row level security;alter table public.vaccinations enable row level security;alter table public.routines enable row level security;alter table public.appointments enable row level security;
create policy "profile own" on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy "dog own" on public.dogs for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "health own" on public.health_records for all using(public.owns_dog(dog_id)) with check(public.owns_dog(dog_id));
create policy "med own" on public.medications for all using(public.owns_dog(dog_id)) with check(public.owns_dog(dog_id));
create policy "vax own" on public.vaccinations for all using(public.owns_dog(dog_id)) with check(public.owns_dog(dog_id));
create policy "routine own" on public.routines for all using(public.owns_dog(dog_id)) with check(public.owns_dog(dog_id));
create policy "appointment own" on public.appointments for all using(public.owns_dog(dog_id)) with check(public.owns_dog(dog_id));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''));return new;end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();